  function customSecondCard(secondCardDiv) {
    const isMobile = window.innerWidth < 1024;
    if (isMobile) {
      const parent = secondCardDiv.parentElement;
      parent.classList.add('new-azul-plus-card');
      parent.lastElementChild.remove();
    }

    let isSecondRateSoldOut = false;

    const newChildContainer = document.createElement('div');
    newChildContainer.classList.add('new-child-plus-container');
    if (isMobile) {
      secondCardDiv.parentElement.appendChild(newChildContainer);
    } else {
      secondCardDiv.appendChild(newChildContainer);
    }

    const parentUl = secondCardDiv.querySelector('ul');

    // removing unnecessary li
    while (parentUl.childElementCount > 1) {
      parentUl.removeChild(parentUl.lastElementChild);
    }

    // Add benefits line
    const benefitsIncludesLine = document.createElement('li');
    benefitsIncludesLine.innerHTML = 'Benefícios incluídos';
    benefitsIncludesLine.classList.add('benefits-line');
    benefitsIncludesLine.style.color = 'white';
    parentUl.appendChild(benefitsIncludesLine);

    mapItems(secondCardListItems, parentUl, true);

    // changing confirm button place
    const firstLi = parentUl.querySelector('li');
    firstLi.classList.add('custom-header');
    const farePrice = firstLi.querySelector('.fare-price');
    farePrice.classList.add('fare-price-custom');

    if (!isMobile) {
      const cardConfirmButton = document.createElement('div');
      cardConfirmButton.classList.add('card-confirm-button');
      cardConfirmButton.innerHTML = 'Selecionar tarifa';
      parentUl.appendChild(cardConfirmButton);

      const originalButton = firstLi.querySelector('button');

      if (
        originalButton &&
        originalButton.getAttribute('aria-label').includes('Tarifa esgotada')
      ) {
        isSecondRateSoldOut = true;
        return;
      }

      originalButton.style.display = 'none';

      cardConfirmButton.addEventListener('click', () => {
        originalButton.click();
        transformChangeFlightButton();
      });
    }

    // add difference value
    const newCardsParentContainer =
      document.querySelector('.new-card-style').parentElement.parentElement;

    const cardContentContainer = isMobile
      ? newCardsParentContainer
      : secondCardDiv.closest('.card-content');
    const { firstCardValue, secondCardValue } =
      getDifferenceValue(cardContentContainer);

    // criar regra também para quando não houver a segunda tarifa
    if (firstCardValue === 'soldOut') {
      const azulPlusTag = firstLi.querySelector('p');
      azulPlusTag.classList.add('white-plus-tag');
      const azulOriginalPrice = firstLi.querySelector('h4');
      azulOriginalPrice.classList.add('sold-out-total-price');
    } else {
      const differenceResult = calcDifference(firstCardValue, secondCardValue);

      // changing header colors
      const azulPlusTag = firstLi.querySelector('p');
      azulPlusTag.classList.add('white-plus-tag');
      const azulOriginalPrice = firstLi.querySelector('h4');
      azulOriginalPrice.innerHTML = 'Total ' + azulOriginalPrice.innerHTML;
      azulOriginalPrice.classList.add('total-price');

      originalPriceParentDiv = azulOriginalPrice.parentElement;
      originalPriceParentDiv.classList.add('price-container');
      const differenceValueDiv = document.createElement('div');
      differenceValueDiv.appendChild(differenceResult);

      originalPriceParentDiv.insertBefore(
        differenceValueDiv,
        azulOriginalPrice
      );
    }

    // split container
    const leftContainerSide = document.createElement('div');
    leftContainerSide.classList.add('plus-left-side-container');

    const rightContainerSide = document.createElement('div');
    rightContainerSide.classList.add('plus-right-side-container');

    let imageUrl =
      'https://www.voeazul.com.br/content/dam/azul/testes-ab/maisBagagem.png';

    let imageUrl2 =
      'https://www.voeazul.com.br/content/dam/azul/testes-ab/maisEspa%c3%a7o.png';

    const imgElement = document.createElement('img');
    imgElement.classList.add('slide-img', 'center-img-bottom');
    imgElement.src = imageUrl;
    imgElement.alt = 'Bagagens no aeroporto';

    const imgElementTwo = document.createElement('img');
    imgElementTwo.classList.add('slide-img');
    imgElementTwo.src = imageUrl2;
    imgElementTwo.alt = 'Bagagens no aeroporto 2';

    if (isMobile) {
      const parent = secondCardDiv.parentElement;
      const emptyLi = parent.querySelector('li');
      emptyLi.remove();
    }

    const swiperContainer = document.createElement('div');
    swiperContainer.classList.add('swiper-test', 'img-container', 'swiper');
    const swiperWrapper = document.createElement('div');
    swiperWrapper.classList.add('swiper-wrapper', 'swiper-wrapper-test');

    const swiperSlide1 = document.createElement('div');
    swiperSlide1.classList.add('swiper-slide', 'relative-slide');

    const swiperSlide2 = document.createElement('div');
    swiperSlide2.classList.add('swiper-slide', 'relative-slide');

    const swiperNextButton = document.createElement('div');
    swiperNextButton.classList.add(
      'swiper-button-next',
      'swiper-button-next-test',
      'swiper-buttons'
    );
    const swiperPrevButton = document.createElement('div');
    swiperPrevButton.classList.add(
      'swiper-button-prev',
      'swiper-button-prev-test',
      'swiper-buttons'
    );

    // criando overlay de botoes
    const overlayButtons = document.createElement('div');
    overlayButtons.classList.add('overlay-buttons-container');

    const prevButton = document.createElement('button');
    prevButton.classList.add('overlay-button');
    prevButton.innerHTML = isMobile ? chevronLeftSVGMobile : chevronLeftSVG;
    prevButton.addEventListener('click', () => {
      swiperPrevButton.click();
    });

    const nextButton = document.createElement('button');
    nextButton.classList.add('overlay-button');
    nextButton.innerHTML = isMobile ? chevronRightSVGMobile : chevronRightSVG;
    nextButton.addEventListener('click', () => {
      swiperNextButton.click();
    });

    overlayButtons.appendChild(prevButton);
    overlayButtons.appendChild(nextButton);

    swiperContainer.appendChild(overlayButtons);
    swiperContainer.appendChild(swiperWrapper);
    swiperWrapper.appendChild(swiperSlide1);
    swiperWrapper.appendChild(swiperSlide2);
    swiperContainer.appendChild(swiperPrevButton);
    swiperContainer.appendChild(swiperNextButton);

    //img 1;
    swiperSlide1.appendChild(imgElement);

    //img 2;
    swiperSlide2.appendChild(imgElementTwo);

    rightContainerSide.appendChild(swiperContainer);

    if (window.swiperAlreadyStarted) {
      buildSwiper();
    }

    const imageBottomTag = document.createElement('div');
    imageBottomTag.classList.add('card-plus-bottom-tag', 'card-absolute');
    imageBottomTag.innerHTML = 'Prioridade no despacho de bagagem';
    swiperSlide1.appendChild(imageBottomTag);

    const imageBottomTag2 = document.createElement('div');
    imageBottomTag2.classList.add('card-plus-bottom-tag', 'card-absolute');
    imageBottomTag2.innerHTML = 'Muito mais espaço durante o voo';
    swiperSlide2.appendChild(imageBottomTag2);

    leftContainerSide.appendChild(parentUl);
    if (!isMobile) {
      newChildContainer.appendChild(leftContainerSide);
      newChildContainer.appendChild(rightContainerSide);
    } else {
      benefitsIncludesLine.insertAdjacentElement(
        'afterend',
        rightContainerSide
      );
      newChildContainer.appendChild(leftContainerSide);
    }

    let points = 0;
    if (!isMobile) {
      const fareButton = secondCardDiv.querySelector('.fare-price-custom');
      const rawValue = fareButton.querySelector('h4');
      points = valueParseFloat(rawValue.textContent) * 4;
    } else {
      const promotionalTag = document.querySelectorAll('.promotional');

      const nextElement =
        promotionalTag[1].parentElement.nextElementSibling.querySelector('h4');

      const rawValue = nextElement.textContent;

      points = valueParseFloat(rawValue) * 4;
    }

    // add bottom tag
    const cardBottomTag = document.createElement('div');
    cardBottomTag.classList.add('card-plus-bottom-tag');

    cardBottomTag.innerHTML =
      '<svg width="17" height="8" viewBox="0 0 17 8" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5.4664 5.92665L3.698 6.30854L4.08214 4.00366L5.4664 5.92665Z" fill="white"/><path d="M3.71094 3.182L3.69175 3.02856L3.57434 2.92792L1.44998 1.10704L3.37005 0.558447H15.3281L8.85837 6.34711L6.52555 7.34689L4.79196 4.91985L4.45511 4.44827L4.13364 4.93047L3.96173 5.18834L3.71094 3.182Z" stroke="white" stroke-width="0.8"/><path d="M3.698 4.3859L15.2224 0.544434" stroke="white" stroke-width="0.8"/></svg><div><b>Ganhe até ' +
      String(formatNumber(points)) +
      '</b> pontos Azul Fidelidade</div>';

    if (isMobile) {
      const parentContainer = document.querySelector('.new-azul-plus-card');
      parentContainer.appendChild(cardBottomTag);
    } else {
      secondCardDiv.appendChild(cardBottomTag);
    }
  }

  function clearState() {
    window.listenerActive = true;
  }

  function customCloseButtons() {
    const header = document.querySelector('.modal-content__header');
    const button = header.querySelector('button');

    const footer = document.querySelector('.modal-content__footer');
    const footerButton = footer.querySelector('button');

    button.addEventListener('click', clearState);
    footerButton.addEventListener('click', clearState);
  }

  function returnOriginalButtons(element) {
    const madeButton = element.querySelector('.fare-selected-button');
    const originalButton = element.querySelector(
      '[data-testid="search-box-hotel-date-picker-primary-button"]'
    );
    if (!originalButton) return;
    if (!madeButton) return;

    if (madeButton && getComputedStyle(originalButton).display === 'flex') {
      const clonedButton = originalButton.cloneNode(true);
      clonedButton.classList.add('card-confirm-button');

      madeButton.style.display = 'none';
      originalButton.style.display = 'none';
      madeButton.replaceWith(clonedButton);
      clonedButton.addEventListener('click', () => {
        originalButton.click();
      });
    }
  }

  function setSelectedButton(parent) {
    const textElements = Array.from(parent.getElementsByTagName('p')).filter(
      (p) => p.textContent.includes('Tarifa selecionada')
    );

    if (textElements.length <= 0) return;

    textElements.forEach((p) => {
      p.style.display = 'none';
    });

    const newButton = document.createElement('button');
    newButton.classList.add('fare-selected-button');
    const svg = parent.classList.contains('new-azul-plus-card')
      ? selectedFareAirplaneWhiteSVG
      : selectedFareAirplaneSVG;
    newButton.innerHTML = svg + String(' Tarifa selecionada');

    const oldButton = parent.querySelector('.card-confirm-button');
    oldButton.replaceWith(newButton);
    oldButton.style.display = 'none';

    if (parent.classList.contains('new-card-style')) {
      newButton.style.color = '#026CB6';
      parent.classList.add('first-selected');
    }
    if (parent.classList.contains('new-azul-plus-card')) {
      newButton.style.color = 'white';
      newButton.style.borderColor = 'white';
    }
  }

  function updateParentClass() {
    const firstCardRef = document.querySelectorAll('.new-child-container');
    const firstCardParents = Array.from(firstCardRef).map(
      (div) => div.parentElement
    );
    const secondCardRef = document.querySelectorAll(
      '.new-child-plus-container'
    );
    const secondCardParents = Array.from(secondCardRef).map(
      (div) => div.parentElement
    );

    firstCardParents.forEach((element) => {
      if (element && !element.classList.contains('new-card-style')) {
        element.classList.add('new-card-style');
        setSelectedButton(element);
      } else {
        returnOriginalButtons(element);
      }
    });

    secondCardParents.forEach((element) => {
      if (element && !element.classList.contains('new-azul-plus-card')) {
        element.classList.add('new-azul-plus-card');
        setSelectedButton(element);
      } else {
        returnOriginalButtons(element);
      }
    });
  }

  function buildSwiper() {
    const swiper = new Swiper('.swiper-test', {
      direction: 'horizontal',
      enabled: 'true',
      wrapperClass: 'swiper-wrapper-test',

      navigation: {
        nextEl: '.swiper-button-next-test',
        prevEl: '.swiper-button-prev-test',
      },
    });
    if (!swiper) {
      return;
    } else {
      window.swiperAlreadyBuilt = true;
      return swiper;
    }
  }

  function closeAllCards() {
    const buttons = document.querySelectorAll('button');
    buttons.forEach((button) => {
      if (button.textContent.trim() === 'Recolher') {
        button.click();
      }
    });
  }

  function startSwiper() {
    const swiperStylesheet = document.createElement('link');
    swiperStylesheet.rel = 'stylesheet';
    swiperStylesheet.href =
      'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css';
    document.head.appendChild(swiperStylesheet);

    const swiperScript = document.createElement('script');
    swiperScript.src =
      'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js';
    swiperScript.onload = () => (window.swiperAlreadyStarted = true);
    document.head.appendChild(swiperScript);
  }

  function mainNewNationalCardExpB() {
    // Adicionando CSS
    const styleTag = document.createElement('style');
    styleTag.innerHTML = cssForNationalCardTestB;
    styleTag.id = 'test-ab';
    document.getElementsByTagName('head')[0].appendChild(styleTag);

    if (!window.swiperAlreadyStarted) {
      startSwiper();
    }

    const isTripInternational = checkIsInternational();
    if (isTripInternational) return;

    const isMobile = window.innerWidth < 1024;

    // Valida se está usando pontos ou reais
    var bookingCalendar = document.querySelector('.booking-calendar__cards');
    if (!bookingCalendar) return;

    const buttons = document.querySelectorAll('button');
    const changeFlightButton = Array.from(buttons).find(
      (el) => el.textContent.trim() === 'Trocar esse voo'
    );
    if (changeFlightButton) {
      changeFlightButton.addEventListener('click', () => {
        clearState();
      });
    }

    const sectionList = document.querySelectorAll('.card-list');
    if (!sectionList) return;

    let allCardsContainer = [];

    const sectionOneArray = Array.from(sectionList[0].children);

    if (sectionList[1]) {
      const sectionTwoArray = Array.from(sectionList[1].children);
      allCardsContainer = [...sectionOneArray, ...sectionTwoArray];
    } else {
      allCardsContainer = [...sectionOneArray];
    }

    if (window.listenerActive && window.swiperAlreadyStarted) {
      if (!isMobile) {
        const textElement = document.querySelectorAll('.button__text');
        if (!textElement) return;

        const searchAgainButton = Array.from(textElement).find(
          (el) => el.textContent.trim() === 'Buscar passagens'
        );

        if (searchAgainButton) {
          searchAgainButton.addEventListener('click', () => {
            execute();
          });
        }

        const containersList = document.querySelectorAll(
          '.flight-card__container'
        );

        if (!containersList) return;

        containersList.forEach((element) => {
          if (element.classList.contains('already-customize')) return;

          element.classList.add('already-customize');
          element.addEventListener('click', () => {
            updateParentClass();
          });
        });

        allCardsContainer.forEach((container) => {
          const flightSoldOut = container.querySelector(
            '[aria-label="Voo esgotado"]'
          );
          if (flightSoldOut) return;

          const contentColumns = container.querySelector('li');
          contentColumns.style.display = 'none';

          const fareItems = container.querySelectorAll('.fare-item');

          if (fareItems[0].classList.contains('new-card-style')) return;
          if (fareItems[1].classList.contains('new-azul-plus-card')) return;

          fareItems[0].classList.add('new-card-style');
          fareItems[1].classList.add('new-azul-plus-card');

          customFirstCard(fareItems[0]);
          customSecondCard(fareItems[1]);
          customBottomInfo(container);
        });

        buildSwiper();

        const showMoreButton = Array.from(document.querySelectorAll('*')).find(
          (el) => el.textContent.trim() === 'Ver mais voos'
        );
        if (showMoreButton) {
          showMoreButton.addEventListener('click', clearState);
        }

        window.listenerActive = false;
      }
    }

    if (isMobile) {
      if (!window.alreadyApplyChanges && window.swiperAlreadyStarted) {
        const fareItems = document.querySelectorAll('.fare-item');
        if (fareItems.length <= 0) return;

        customFirstCard(fareItems[0]);
        customSecondCard(fareItems[1]);

        customCloseButtons();
        buildSwiper();

        const customDots = document.querySelector('.custom-dots');
        const originalBottomInfo = customDots.parentElement.nextElementSibling;
        customBottomInfo(originalBottomInfo);
        window.alreadyApplyChanges = true;
      }
    }
  }

  execute();